import{_ as e,o as r,c as l,a2 as a}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"Ceph Orchestrator Meeting 2023-03-14","description":"","frontmatter":{"title":"Ceph Orchestrator Meeting 2023-03-14","date":"2023-03-14T00:00:00.000Z","updated":"2023-03-15T00:00:00.000Z","tags":["Ceph","分布式存储","OSD Flags","升级过程","OpenStack Manila","Ceph NFS服务"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-03-14.md","filePath":"posts/2023/Ceph_Orchestrator_Meeting_2023-03-14.md","lastUpdated":1780459816000}'),s={name:"posts/2023/Ceph_Orchestrator_Meeting_2023-03-14.md"};function i(o,t,n,g,p,h){return r(),l("div",null,[...t[0]||(t[0]=[a('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>OSD Flags 处理机制讨论</strong></p><ul><li><strong>背景</strong>：会议讨论了OSD Flags的处理机制，特别是在升级过程中。</li><li><strong>当前方案</strong>：目前方案允许通过逗号分隔的列表配置OSD Flags，默认情况下进行升级时设置这些标志。</li><li><strong>讨论点</strong>： <ul><li>是否应该默认设置标志，以及如何处理用户已设置的标志。</li><li>使用逗号分隔列表作为配置选项的优缺点。</li><li>评估用户修改标志频率以决定配置的复杂度和灵活性。</li></ul></li><li><strong>决定事项</strong>：同意在升级前保存标志状态并在升级后恢复，避免用户设置被意外更改。</li><li><strong>后续行动计划</strong>：开发团队将实现升级前保存标志状态并在升级后恢复的功能。</li></ul></li><li><p><strong>升级过程中的标志处理</strong></p><ul><li><strong>问题</strong>：如果用户已设置某些标志，升级过程中是否应该保留这些设置。</li><li><strong>建议</strong>：在升级前保存当前标志状态，并在升级后恢复，以避免意外更改用户设置。</li></ul></li><li><p><strong>新功能引入与默认行为</strong></p><ul><li><strong>讨论</strong>：是否应该在旧版本中引入新功能但不改变默认行为，以避免用户感到意外。</li><li><strong>建议</strong>：在旧版本中引入机制但不启用默认行为，在主要版本更新时再启用新默认行为。</li></ul></li><li><p><strong>OpenStack Manila与Ceph NFS服务集成</strong></p><ul><li><strong>背景</strong>：讨论了与OpenStack Manila集成的相关问题和解决方案，特别是关于Ingress服务的配置和NFS Ganesha的代理协议实现。</li><li><strong>决定事项</strong>：与NFS Ganesha开发者合作，实现代理协议，允许NFS连接查看实际客户端地址，从而支持客户端限制。</li></ul></li></ol><h4 id="会议结束" tabindex="-1">会议结束 <a class="header-anchor" href="#会议结束" aria-label="Permalink to &quot;会议结束&quot;">​</a></h4><ul><li>会议在讨论完所有议题后结束，预计下次会议将继续跟进相关议题的进展。</li></ul>',5)])])}const d=e(s,[["render",i]]);export{c as __pageData,d as default};
